pub type Stack = { items: Vec[Int]; }

fn Stack.new() -> Stack {
  return Stack{ items: Vec[Int]() };
}

fn Stack.push(self: &mut Stack, item: Int) -> Unit {
  self.items.push(item);
}

fn Stack.pop(self: &mut Stack) -> Option[Int] {
  return self.items.pop();
}

fn main() -> Int {
  var s = Stack.new();
  s.push(1);
  s.push(2);
  s.push(3);
  var sum = 0;
  while true {
    match s.pop() {
      Some(n) => { sum = sum + n; }
      None => { break; }
    }
  }
  return sum;
}
